import { crc32, deflateRawSync } from "node:zlib";
import { afterEach, describe, expect, it, vi } from "vitest";
import { InspectionToolMissingError, readPostMergeArtifact } from "../executor/read-post-merge-artifact.js";

const input = { repository: "Runfusion/Fusion", artifactId: 42, cwd: "/repo" };
const MAX_BYTES = 2 * 1024 * 1024;

// Generated by Python 3.12 zipfile writing to a non-seekable stream (as streamed GitHub artifacts are), so entries carry data descriptors (flag bit 3): evidence.json, nested/, and deflated nested/summary.txt ("ok\n" x 50).
const REAL_TOOL_FIXTURE = Buffer.from(
  "",
  "base64",
);

interface EntrySpec {
  name: string | Buffer;
  content?: string | Buffer;
  method?: number;
  flags?: number;
  data?: Buffer;
  declaredSize?: number;
  crc?: number;
}

/** Build archives that real zip tools refuse to produce (bombs, bad names, unsupported features). */
function buildZip(specs: EntrySpec[], endOverrides: { totalEntries?: number } = {}): Buffer {
  const locals: Buffer[] = [];
  const centrals: Buffer[] = [];
  let offset = 0;
  for (const spec of specs) {
    const name = Buffer.isBuffer(spec.name) ? spec.name : Buffer.from(spec.name);
    const content = Buffer.isBuffer(spec.content) ? spec.content : Buffer.from(spec.content ?? "");
    const method = spec.method ?? 8;
    const data = spec.data ?? (method === 8 ? deflateRawSync(content) : content);
    const checksum = spec.crc ?? (crc32(content) >>> 0);
    const size = spec.declaredSize ?? content.length;
    const flags = spec.flags ?? 0;
    const local = Buffer.alloc(30 + name.length);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(flags, 6);
    local.writeUInt16LE(method, 8);
    local.writeUInt32LE(checksum, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(size, 22);
    local.writeUInt16LE(name.length, 26);
    name.copy(local, 30);
    const central = Buffer.alloc(46 + name.length);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4);
    central.writeUInt16LE(20, 6);
    central.writeUInt16LE(flags, 8);
    central.writeUInt16LE(method, 10);
    central.writeUInt32LE(checksum, 16);
    central.writeUInt32LE(data.length, 20);
    central.writeUInt32LE(size, 24);
    central.writeUInt16LE(name.length, 28);
    central.writeUInt32LE(offset, 42);
    name.copy(central, 46);
    locals.push(local, data);
    centrals.push(central);
    offset += local.length + data.length;
  }
  const directory = Buffer.concat(centrals);
  const end = Buffer.alloc(22);
  const totalEntries = endOverrides.totalEntries ?? specs.length;
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(totalEntries, 8);
  end.writeUInt16LE(totalEntries, 10);
  end.writeUInt32LE(directory.length, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...locals, directory, end]);
}

function spawnMissing(binary: string): Error {
  return Object.assign(new Error(`spawn ${binary} ENOENT`), { code: "ENOENT", syscall: `spawn ${binary}`, path: binary });
}

/** A host with `gh` and no other binary: only the download is injected; parsing runs on real bytes. */
function ghReturning(archive: Buffer) {
  return vi.fn(async (binary: string, _args: string[], _options: { timeout: number; maxBuffer: number; signal?: AbortSignal }) => {
    if (binary !== "gh") throw spawnMissing(binary);
    return { stdout: archive };
  });
}

afterEach(() => {
  vi.useRealTimers();
});

describe("bounded post-merge artifact inspection", () => {
  it("reads a streamed real-tool archive in memory with gh as the only spawned program", async () => {
    expect(REAL_TOOL_FIXTURE.readUInt16LE(6) & 0x8).toBe(0x8);
    const run = ghReturning(REAL_TOOL_FIXTURE);
    const output = await readPostMergeArtifact(input, run);
    expect(output).toContain('--- evidence.json ---\n{"failedJobs":[]}');
    expect(output).toContain(`--- nested/summary.txt ---\n${"ok\n".repeat(50)}`);
    expect(output).not.toContain("--- nested/ ---");
    expect(run).toHaveBeenCalledTimes(1);
    expect(run).toHaveBeenCalledWith("gh", ["api", "--method", "GET", "repos/Runfusion/Fusion/actions/artifacts/42/zip"], expect.anything());
    const { timeout } = run.mock.calls[0][2];
    expect(timeout).toBeGreaterThan(0);
    expect(timeout).toBeLessThanOrEqual(30_000);
  });

  it("reads stored and duplicate entries in central-directory order", async () => {
    const archive = buildZip([{ name: "a.txt", content: "first", method: 0 }, { name: "a.txt", content: "second" }]);
    await expect(readPostMergeArtifact(input, ghReturning(archive))).resolves.toBe("\n--- a.txt ---\nfirst\n--- a.txt ---\nsecond");
  });

  it("reads an archive with no entries as empty output", async () => {
    await expect(readPostMergeArtifact(input, ghReturning(buildZip([])))).resolves.toBe("");
  });

  it("accepts 32 entries", async () => {
    const archive = buildZip(Array.from({ length: 32 }, (_, index) => ({ name: `${index}.json`, content: "x" })));
    await expect(readPostMergeArtifact(input, ghReturning(archive))).resolves.toContain("--- 31.json ---\nx");
  });

  it("caps archive entry count before reading any content", async () => {
    // Every entry fails its CRC, so reading any content would report corruption instead of the cap.
    const archive = buildZip(Array.from({ length: 33 }, (_, index) => ({ name: `${index}.json`, content: "x", crc: 1 })));
    await expect(readPostMergeArtifact(input, ghReturning(archive))).rejects.toThrow("too many entries");
  });

  it("rejects an oversized compressed download before parsing", async () => {
    const run = ghReturning(Buffer.alloc(MAX_BYTES + 1));
    await expect(readPostMergeArtifact(input, run)).rejects.toThrow("size limit");
    expect(run).toHaveBeenCalledTimes(1);
  });

  it("rejects an entry whose declared size exceeds the remaining budget", async () => {
    const archive = buildZip([{ name: "big.bin", content: "x", declaredSize: MAX_BYTES + 1 }]);
    await expect(readPostMergeArtifact(input, ghReturning(archive))).rejects.toThrow("size limit");
  });

  it("refuses a deflate bomb whose inflated output exceeds the budget", async () => {
    const bomb = Buffer.alloc(3 * MAX_BYTES);
    const archive = buildZip([{ name: "bomb.bin", data: deflateRawSync(bomb), declaredSize: 10, crc: crc32(bomb) >>> 0 }]);
    expect(archive.length).toBeLessThan(MAX_BYTES);
    await expect(readPostMergeArtifact(input, ghReturning(archive))).rejects.toThrow(/size limit|corrupt/);
  });

  it("rejects entries whose cumulative size crosses the budget", async () => {
    const half = Buffer.alloc(Math.ceil(MAX_BYTES * 0.55), "a");
    const archive = buildZip([{ name: "one.txt", content: half }, { name: "two.txt", content: half }]);
    await expect(readPostMergeArtifact(input, ghReturning(buildZip([{ name: "one.txt", content: half }])))).resolves.toContain("--- one.txt ---");
    await expect(readPostMergeArtifact(input, ghReturning(archive))).rejects.toThrow("size limit");
  });

  it.each<[string, string | Buffer]>([
    ["parent traversal", "../escape.json"],
    ["inner traversal", "a/../b.json"],
    ["absolute path", "/absolute.json"],
    ["option-like name", "-option"],
    ["glob star", "*.json"],
    ["glob bracket", "a[1].json"],
    ["backslash", "dir\\file.json"],
    ["control character", "ctrl\u0001.json"],
    ["invalid UTF-8", Buffer.from([0x66, 0xff, 0x2e, 0x6a])],
  ])("rejects an unsafe %s entry name before reading any content", async (_label, name) => {
    // The readable entry fails its CRC, so validation must run before content reads for the name error to win.
    const archive = buildZip([{ name: "ok.json", content: "{}", crc: 1 }, { name, content: "x" }]);
    await expect(readPostMergeArtifact(input, ghReturning(archive))).rejects.toThrow("unsupported entry name");
  });

  it.each<[string, Buffer]>([
    ["non-zip bytes", Buffer.from("archive")],
    ["a truncated archive", REAL_TOOL_FIXTURE.subarray(0, REAL_TOOL_FIXTURE.length - 10)],
    ["a CRC mismatch", buildZip([{ name: "evidence.json", content: "{}", crc: 1 }])],
  ])("rejects %s as corrupt", async (_label, archive) => {
    await expect(readPostMergeArtifact(input, ghReturning(archive))).rejects.toThrow("corrupt or not a zip file");
  });

  it.each<[string, Buffer]>([
    ["an encrypted entry", buildZip([{ name: "secret.json", content: "{}", flags: 0x1 }])],
    ["an unsupported compression method", buildZip([{ name: "lzma.json", content: "{}", method: 12 }])],
    ["a zip64 entry-count marker", buildZip([{ name: "a.json", content: "{}" }], { totalEntries: 0xffff })],
  ])("rejects %s as an unsupported zip feature", async (_label, archive) => {
    await expect(readPostMergeArtifact(input, ghReturning(archive))).rejects.toThrow("unsupported zip feature");
  });

  it("reports a missing gh as a distinct missing-tool error", async () => {
    const run = vi.fn(async (binary: string) => {
      throw spawnMissing(binary);
    });
    const failure = await readPostMergeArtifact(input, run).catch((error: unknown) => error);
    expect(failure).toBeInstanceOf(InspectionToolMissingError);
    expect(failure).toMatchObject({ tool: "gh" });
  });

  it("keeps a non-spawn ENOENT as ordinary failure", async () => {
    const run = vi.fn(async () => {
      throw Object.assign(new Error("ENOENT: no such file or directory"), { code: "ENOENT", syscall: "open" });
    });
    const failure = await readPostMergeArtifact(input, run).catch((error: unknown) => error);
    expect(failure).not.toBeInstanceOf(InspectionToolMissingError);
    expect(failure).toMatchObject({ message: "ENOENT: no such file or directory" });
  });

  it("does not download when the signal is already aborted", async () => {
    const run = ghReturning(REAL_TOOL_FIXTURE);
    await expect(readPostMergeArtifact({ ...input, signal: AbortSignal.abort() }, run)).rejects.toMatchObject({ name: "AbortError" });
    expect(run).not.toHaveBeenCalled();
  });

  it("stops before reading entries when aborted during the download", async () => {
    const controller = new AbortController();
    // A CRC failure would surface if any entry were read after the abort.
    const archive = buildZip([{ name: "evidence.json", content: "{}", crc: 1 }]);
    const run = vi.fn(async () => {
      controller.abort();
      return { stdout: archive };
    });
    await expect(readPostMergeArtifact({ ...input, signal: controller.signal }, run)).rejects.toMatchObject({ name: "AbortError" });
  });

  it("times out before reading entries once the deadline has passed", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(0);
    const archive = buildZip([{ name: "evidence.json", content: "{}", crc: 1 }]);
    const run = vi.fn(async () => {
      vi.setSystemTime(30_001);
      return { stdout: archive };
    });
    await expect(readPostMergeArtifact(input, run)).rejects.toThrow("timed out");
  });

  it("rejects arbitrary endpoints before executing commands", async () => {
    const run = vi.fn();
    await expect(readPostMergeArtifact({ ...input, repository: "https://example.org" }, run)).rejects.toThrow("owner/repository");
    await expect(readPostMergeArtifact({ ...input, artifactId: -1 }, run)).rejects.toThrow("artifact ID");
    expect(run).not.toHaveBeenCalled();
  });
});
